Literal.Value:
'{
 "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
 "description": "Curva de Lorenz · concentracao de receita por cliente · area de Gini demarcada",
 "background": "transparent",
 "padding": {
  "top": 6,
  "left": 2,
  "right": 6,
  "bottom": 2
 },
 "width": "container",
 "height": "container",
 "config": {
  "view": {
   "stroke": null
  },
  "font": "Segoe UI",
  "axis": {
   "domain": false,
   "tickColor": "rgba(255,255,255,0.15)",
   "gridColor": "rgba(255,255,255,0.06)",
   "labelColor": "#C8C8D0",
   "titleColor": "#F4F4F5",
   "labelFontSize": 11,
   "titleFontSize": 12
  }
 },
 "data": {
  "name": "dataset"
 },
 "transform": [
  {
   "window": [
    {
     "op": "sum",
     "field": "Monetary",
     "as": "cum_revenue"
    }
   ],
   "sort": [
    {
     "field": "Monetary",
     "order": "descending"
    }
   ],
   "frame": [
    null,
    0
   ]
  },
  {
   "window": [
    {
     "op": "count",
     "as": "rank"
    }
   ],
   "sort": [
    {
     "field": "Monetary",
     "order": "descending"
    }
   ],
   "frame": [
    null,
    0
   ]
  },
  {
   "joinaggregate": [
    {
     "op": "max",
     "field": "cum_revenue",
     "as": "total_revenue"
    },
    {
     "op": "count",
     "as": "total_n"
    }
   ]
  },
  {
   "calculate": "datum.rank / datum.total_n",
   "as": "pct_clients"
  },
  {
   "calculate": "datum.cum_revenue / datum.total_revenue",
   "as": "pct_revenue"
  }
 ],
 "layer": [
  {
   "description": "AREA DE GINI · entre a linha de igualdade (y=x) e a curva de Lorenz",
   "mark": {
    "type": "area",
    "color": "#F2C94C",
    "opacity": 0.16,
    "interpolate": "monotone",
    "clip": true
   },
   "encoding": {
    "x": {
     "field": "pct_clients",
     "type": "quantitative",
     "scale": {
      "domain": [
       0,
       1
      ]
     },
     "title": "% acumulado de clientes",
     "axis": {
      "format": ".0%",
      "grid": true,
      "tickCount": 5
     }
    },
    "y": {
     "field": "pct_clients",
     "type": "quantitative",
     "scale": {
      "domain": [
       0,
       1
      ]
     },
     "title": "% receita acumulada",
     "axis": {
      "format": ".0%",
      "grid": true,
      "tickCount": 5
     }
    },
    "y2": {
     "field": "pct_revenue"
    }
   }
  },
  {
   "description": "linha de igualdade perfeita (45 graus)",
   "data": {
    "values": [
     {
      "x": 0,
      "y": 0
     },
     {
      "x": 1,
      "y": 1
     }
    ]
   },
   "mark": {
    "type": "line",
    "color": "#71717A",
    "strokeDash": [
     4,
     4
    ],
    "opacity": 0.55,
    "clip": true
   },
   "encoding": {
    "x": {
     "field": "x",
     "type": "quantitative",
     "scale": {
      "domain": [
       0,
       1
      ]
     },
     "title": "% acumulado de clientes"
    },
    "y": {
     "field": "y",
     "type": "quantitative",
     "scale": {
      "domain": [
       0,
       1
      ]
     },
     "title": "% receita acumulada"
    }
   }
  },
  {
   "description": "curva de Lorenz",
   "mark": {
    "type": "line",
    "color": "#A78BFA",
    "strokeWidth": 2.5,
    "interpolate": "monotone",
    "tooltip": true,
    "clip": true
   },
   "encoding": {
    "x": {
     "field": "pct_clients",
     "type": "quantitative",
     "title": "% acumulado de clientes",
     "scale": {
      "domain": [
       0,
       1
      ]
     },
     "axis": {
      "format": ".0%"
     }
    },
    "y": {
     "field": "pct_revenue",
     "type": "quantitative",
     "scale": {
      "domain": [
       0,
       1
      ]
     },
     "axis": {
      "format": ".0%"
     },
     "title": "% receita acumulada"
    },
    "tooltip": [
     {
      "field": "pct_clients",
      "type": "quantitative",
      "title": "% clientes",
      "format": ".1%"
     },
     {
      "field": "pct_revenue",
      "type": "quantitative",
      "title": "% receita",
      "format": ".1%"
     }
    ]
   }
  },
  {
   "description": "insight: top 20% dos clientes concentram 54% da receita",
   "data": {
    "values": [
     {
      "x": 0.97,
      "y": 0.1,
      "label": "20% dos clientes = 54% da receita"
     }
    ]
   },
   "mark": {
    "type": "text",
    "color": "#F2C94C",
    "fontSize": 11,
    "fontWeight": 600,
    "align": "right",
    "baseline": "bottom"
   },
   "encoding": {
    "x": {
     "field": "x",
     "type": "quantitative",
     "title": "% acumulado de clientes",
     "scale": {
      "domain": [
       0,
       1
      ]
     }
    },
    "y": {
     "field": "y",
     "type": "quantitative",
     "title": "% receita acumulada",
     "scale": {
      "domain": [
       0,
       1
      ]
     }
    },
    "text": {
     "field": "label"
    }
   }
  }
 ]
}'
